@RunWith(MockitoJUnitRunner.class)
public class IndexResourceTest {}
/**************TEST SETUP BEGIN*************/
@Before
public void setUp(){
        resource = new IndexResource();
        ReflectionTestUtils.setField(resource, "emf", emf);
        ReflectionTestUtils.setField(resource, "management", management);
        ReflectionTestUtils.setField(resource, "properties", properties);
        ReflectionTestUtils.setField(resource, "tokens", tokens);
        ReflectionTestUtils.setField(resource, "smf", smf);
        ReflectionTestUtils.setField(resource, "qmf", qmf);
        ReflectionTestUtils.setField(resource, "injector", injector);

        when(management.getOrganizationConfigDefaultsOnly()).thenReturn(orgConfig);
        when(injector.getInstance(ReIndexService.class)).thenReturn(reIndexService);
        when(reIndexService.rebuildIndex(any(org.apache.usergrid.corepersistence.index.ReIndexRequestBuilder.class)))
            .thenReturn(reIndexStatus);
        when(reIndexStatus.getJobId()).thenReturn("job-123");
        when(reIndexStatus.getStatus()).thenReturn(ReIndexService.Status.COMPLETE);
        when(reIndexStatus.getLastUpdated()).thenReturn(System.currentTimeMillis());
        when(reIndexStatus.getNumberProcessed()).thenReturn(50L);
        when(reIndexStatus.getCollectionName()).thenReturn(null);
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void rebuildIndexesPut_withZeroUpdated_resumesRebuild() throws Exception{
        Map<String, Object> payload = new HashMap<>();
        payload.put("updated", 0);

        ApiResponse response = resource.rebuildIndexesPut(payload, "callback");

        assertNotNull(response);
        assertEquals("rebuild indexes", response.getAction());
        assertEquals("ok", response.getStatus());
    }
/**************TEST METHOD END*************/


